import{_ as o,l,o as e,c as E,v as t,p as s,x as r,d as n,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const _=JSON.parse('{"title":"E4M3 / E5M2","description":"","frontmatter":{"title":"E4M3 / E5M2","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/fp8-formats.md","filePath":"llm/fp8-formats.md","lastUpdated":1789023840000}'),P={name:"llm/fp8-formats.md"};function m(h,a,c,f,T,A){const i=l("Mermaid");return e(),E("div",null,[a[1]||(a[1]=t('<h1 id="e4m3-e5m2" tabindex="-1">E4M3 / E5M2 <a class="header-anchor" href="#e4m3-e5m2" aria-label="Permalink to &quot;E4M3 / E5M2&quot;">​</a></h1><div class="epigraph"><p>FP8 仍是浮点：指数决定动态范围，尾数决定精度。E4M3 多给尾数，E5M2 多给指数。同一 8 bit，对准的是计算核，不是 GPTQ 那种整数格子。</p><footer>—— 对照 NVIDIA/Intel/ARM 的 FP8 白皮书与 OCP 8-bit 浮点约定；训练配方另见通信 dtype</footer></div><p><a href="/llm/nf4-quantile">NF4</a> 是存储用的分位整数码本。本课 <strong>E4M3 / E5M2</strong> 是 8-bit 浮点格式，面向 Tensor Core 上的乘加。缺口：它们是非均匀（指数编码），但不是学出来的码本；溢出、NaN、以及缩放（loss scale / 逐块 scale）是一等公民。<a href="/llm/accelerator-comparison-method">加速器对比</a> 里「有没有 FP8 核」指这一对，不是 NF4。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>E4M3：4 bit 指数、3 bit 尾数，精度相对好，动态范围窄，易溢出，适合需要准的前向权重/激活。E5M2：5 bit 指数、2 bit 尾数，范围更像 FP16 的缩小版，精度更糙，常放梯度或需要范围的张量。两者都是 8 bit，不能混用同一解释。</p><p>没有逐块或逐张量缩放时，Transformer 的激活离群会把 E4M3 打进 inf。FP8 训练是「格式 + 缩放策略 + 核」，缺一不可。问题是 <strong>把哪类张量放进哪一格式</strong>，以及与 PTQ INT8 的关系：FP8 常走训练/推理的原生核，INT8 常走事后量化。</p><p><span class="marginnote">OCP 与厂商白皮书对 E4M3 的 NaN / inf 行为有具体约定（有的变体几乎不用 inf）。实现必须跟核，不要假设 IEEE FP16 的语义缩小。本课不编造未写入公开格式文档的 bit 图案。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>训练：前向 E4M3、反向梯度 E5M2 是常见分工（以你用的框架默认与论文配方为准，换代会变）。必须有溢出监控与缩放更新。推理：权重、激活都 FP8 可吃 Tensor Core；KV 是否 FP8 另算，精度与长度敏感。</p><p>与 INT PTQ：FP8 推理往往是训练就在 FP8 或 QAT；把 FP16 模型事后「铸」成 FP8 仍要校准尺度，近似 W8A8，但格子是浮点不是均匀 INT。不要把 GPTQ 的 4-bit 整数检查点当成 E4M3。</p>',10)),(e(),s(d,null,{default:r(()=>[p(i,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20E43%5B%22E4M3%20%E5%A4%9A%E5%B0%BE%E6%95%B0%22%5D%20--%3E%20FWD%5B%22%E5%89%8D%E5%90%91%20%2F%20%E9%9C%80%E7%B2%BE%E5%BA%A6%22%5D%0A%20%20E52%5B%22E5M2%20%E5%A4%9A%E6%8C%87%E6%95%B0%22%5D%20--%3E%20GRAD%5B%22%E6%A2%AF%E5%BA%A6%20%2F%20%E9%9C%80%E8%8C%83%E5%9B%B4%22%5D%0A%20%20SCALE%5B%22%E9%80%90%E5%9D%97%E6%88%96%E6%8D%9F%E5%A4%B1%E7%BC%A9%E6%94%BE%22%5D%20--%3E%20E43%0A%20%20SCALE%20--%3E%20E52%0A%20%20HW%5B%22FP8%20Tensor%20Core%22%5D%20--%3E%20E43%0A%20%20HW%20--%3E%20E52%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>通信：<a href="/llm/pretrain-comm">预训练通信</a> 的梯度 FP8 通信是另一开关，格式可能与计算 FP8 对齐，协议必须全集群一致。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>浮点的非均匀来自指数：靠近零（正规数范围内）相对精度大约恒定（尾数 bit），而不是均匀 INT 的绝对台阶恒定。对近似对数动态范围的张量，这比 INT8 更省心；对已经平滑到良好范围的张量，INT8 可能更准或核更成熟。离群仍会占满指数的高端，该通道其余值下溢——平滑与混精并不过时。</p><p>E4M3 范围不够时不是「换 E5M2 就结束」，梯度要范围、权重要精度，拆张量类型才是机制。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要在没有 FP8 核的加速器上用软件模拟当对比成绩。不要混用不同厂商的 FP8 变体检查点。不要把 FP8 与 INT8 的 PPL 差写成「8 bit 就是 8 bit」。下一课开始验收：误差度量，适用于 INT 与 FP 格子。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>E4M3 偏精度，E5M2 偏范围；都是 8-bit 浮点核格式。</li><li>必须配缩放；离群照样溢出或下溢。</li><li>与 GPTQ/NF4 检查点不互换；与梯度 FP8 通信要对齐协议。</li><li>对比加速器时 FP8 是计算维，不是存储码本维。</li><li>出处：FP8 白皮书与 OCP 8-bit 浮点约定；框架训练配方。</li></ul>',8))])}const b=o(P,[["render",m]]);export{_ as __pageData,b as default};
